// Pure validation logic for herb profiles generated by herb-profile.js.
// Deliberately has zero imports/dependencies (no Anthropic SDK, no
// Supabase) so it can be required and unit-tested directly with plain
// node, without needing API keys or network access.

// herbalActions/compounds/bodyEffects have no fallback now that there's
// no Stage 1 — if they're empty here, they're empty everywhere. Same for
// spiritualHistory/modernUse, which were always Stage-2-only content.
// functionalOverview is NOT in this list, even though it's a real field —
// it overlaps enough with summary/modernUse that the model sometimes
// treats it as redundant and skips it. Rather than spend a retry chasing
// a field we can reliably derive, deriveFunctionalOverview() builds one
// from modernUse (or summary) whenever it comes back empty.
const REQUIRED_TEXT = ['name', 'latin', 'category', 'summary', 'safetyLevel'];

// herbalActions/compounds/bodyEffects require a NON-EMPTY array — every
// herb genuinely has at least one action/compound/effect, so an empty
// array here really does mean the model skipped the field.
// CRITICAL: compounds must be non-empty AND contain only REAL compounds after validation
const REQUIRED_SECTIONS = ['herbalActions', 'compounds', 'bodyEffects'];

const REQUIRED_TEXT_SECTIONS = {
  spiritualHistory: h => h.spiritualHistory && h.spiritualHistory.overview && h.spiritualHistory.overview.trim(),
  modernUse: h => h.modernUse && h.modernUse.trim()
};

// Optional fields (new custom fields) — don't block profile if missing for backwards compat
const OPTIONAL_TEXT_SECTIONS = {
  keyCharacteristics: h => h.keyCharacteristics && h.keyCharacteristics.trim(),
  growingInformation: h => h.growingInformation && h.growingInformation.trim(),
  usesApplications: h => h.usesApplications && h.usesApplications.trim(),
  herbalCombinations: h => h.herbalCombinations && h.herbalCombinations.trim(),
  harvestingStorage: h => h.harvestingStorage && h.harvestingStorage.trim()
};

// interactions was previously unenforced entirely — it could be missing or
// present and nothing would catch it. It's the field most tied to why this
// site exists (knowing what a herb clashes with), so it's worth requiring
// the model to have actually CONSIDERED it. But unlike herbalActions/
// compounds/bodyEffects, an empty array here can be a legitimate, honest
// answer — plenty of mild culinary herbs genuinely have no significant
// documented interactions. Forcing non-empty would push the model toward
// inventing a plausible-sounding clash just to satisfy the check, which is
// worse than no data for a safety-focused tool. So this only requires the
// KEY to exist as an array (present, even if empty) — not that it's
// non-empty — catching "model skipped the field" without incentivizing
// fabricated interactions.
function hasInteractionsField(h) {
  return Array.isArray(h.interactions);
}

function findMissing(h) {
  const missing = [];
  REQUIRED_TEXT.forEach(f => { if (!h[f] || !String(h[f]).trim()) missing.push(f); });
  REQUIRED_SECTIONS.forEach(f => { if (!Array.isArray(h[f]) || h[f].length === 0) missing.push(f); });
  Object.entries(REQUIRED_TEXT_SECTIONS).forEach(([f, check]) => { if (!check(h)) missing.push(f); });
  if (!h.preparation || Object.values(h.preparation).every(v => !v)) missing.push('preparation');
  if (!hasInteractionsField(h)) missing.push('interactions (as an array — an empty array is fine if there are genuinely none, but the field must be present)');
  return missing;
}

// If functionalOverview came back empty, build a serviceable one instead
// of showing "not recorded" — modernUse's opening is the closest existing
// content to what functionalOverview is meant to say, with summary as a
// second fallback if modernUse is somehow also missing.
function deriveFunctionalOverview(h) {
  if (h.functionalOverview && h.functionalOverview.trim()) return;
  if (h.modernUse && h.modernUse.trim()) {
    const sentences = h.modernUse.trim().split(/(?<=[.!?])\s+/).filter(Boolean);
    h.functionalOverview = sentences.slice(0, 2).join(' ');
  } else if (h.summary && h.summary.trim()) {
    h.functionalOverview = h.summary.trim();
  }
}

// Real herbal compounds — model is only allowed to use these.
// Filters out any made-up compound names before profile display.
const REAL_COMPOUNDS = new Set([
  'baicalein', 'quercetin', 'curcumin', 'gingerol', 'shogaol', 'piperine',
  'resveratrol', 'kaempferol', 'apigenin', 'luteolin', 'naringenin',
  'diosmin', 'hesperidin', 'rutin', 'catechin', 'epicatechin',
  'gallic acid', 'ellagic acid', 'tannic acid', 'caffeine', 'theobromine',
  'alkaloid', 'flavonoid', 'terpenoid', 'saponin', 'glycoside', 'phenolic acid',
  'polysaccharide', 'tannin', 'coumarin', 'lignin', 'volatile oil',
  'essential oil', 'resin', 'glycoprotein', 'polyphenol', 'anthocyanin',
  'chlorogenic acid', 'isoflavone', 'lignan', 'sesquiterpene', 'monoterpene',
  'caffeic acid', 'ferulic acid', 'silybin', 'silymarin', 'berberine',
  'capsaicin', 'allicin', 'sulforaphane', 'indole', 'glucosinolate',
  'betalain', 'carotenoid', 'xanthophyll', 'lycopene', 'beta-carotene',
  'lutein', 'zeaxanthin', 'astaxanthin', 'capsanthin', 'chrysin',
  'daidzein', 'genistein', 'ginsenoside', 'withaferin a', 'withanolide',
  'thymol', 'carvacrol', 'eugenol', 'linalool', 'geraniol', 'citral',
  'menthol', 'camphor', 'borneol', 'turpineol', 'pinene', 'limonene',
  'myrcene', 'caryophyllene', 'humulene', 'farnesene', 'bisabolene',
  'sabinene', 'rosmarinic acid', 'carnosic acid', 'carnosol', 'ursolic acid',
  'oleanolic acid', 'squalene', 'phytosterol', 'stigmasterol',
  'campesterol', 'brassicasterol', 'avenasterol', 'fucoxanthin'
]);

// Strip out fake/unknown compound names before display.
// Keeps only compounds in the REAL_COMPOUNDS whitelist.
function validateCompounds(h) {
  if (!h.compounds || !Array.isArray(h.compounds)) return;
  h.compounds = h.compounds.filter(c => {
    if (!c || !c.name) return false;
    const normalized = c.name.toLowerCase().trim();
    return REAL_COMPOUNDS.has(normalized);
  });
}

// ── Compound verification (replaces the strip-only whitelist) ──────────
// The whitelist above was only ever a shortlist. Real compounds that weren't
// on it (e.g. inulin in burdock) were deleted, the profile was saved with no
// compounds, and the cache then treated it as incomplete and paid to
// regenerate it on every visit.
//
// verifyCompounds() keeps the whitelist as a fast path, then asks PubChem
// (the US National Library of Medicine chemical database) about anything
// else. Each compound ends up as one of:
//   verified: 'list'      — on the known list above (no network needed)
//   verified: 'pubchem'   — PubChem recognises the name; pubchemCid saved
//   verified: 'unchecked' — PubChem couldn't be reached; kept in storage,
//                           hidden from users, re-checked on the next visit
// Names PubChem says don't exist are removed.
//
// What this proves: the compound is a real, documented chemical.
// What it does NOT prove: that this particular herb contains it.
//
// The lookup function is passed in (herb-profile.js supplies it) so this
// file stays free of network code and can still be tested with plain node.
function cleanCompoundName(name) {
  return String(name || '')
    .replace(/\([^)]*\)/g, ' ')      // "Curcumin (diferuloylmethane)" -> "Curcumin"
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function singularOf(n) {
  if (n.length > 4 && n.endsWith('s') && !/(ss|us|is)$/.test(n)) return n.slice(0, -1);
  return null;
}

function onKnownList(n) {
  if (REAL_COMPOUNDS.has(n)) return true;
  const one = singularOf(n);
  return !!(one && REAL_COMPOUNDS.has(one));
}

async function verifyCompounds(h, lookup) {
  const result = { changed: false, unchecked: 0 };
  if (!Array.isArray(h.compounds)) { h.compounds = []; result.changed = true; }
  const before = JSON.stringify(h.compounds);

  const checked = await Promise.all(h.compounds.map(async c => {
    if (!c || !c.name || !String(c.name).trim()) return null;
    if (c.verified === 'list' || c.verified === 'pubchem') return c;   // already settled

    const n = cleanCompoundName(c.name);
    if (!n) return null;
    if (onKnownList(n)) return Object.assign(c, { verified: 'list' });
    if (typeof lookup !== 'function') return Object.assign(c, { verified: 'unchecked' });

    let r = await lookup(n);
    const one = singularOf(n);
    if (r && r.status === 'notfound' && one) r = await lookup(one);

    if (r && r.status === 'found') return Object.assign(c, { verified: 'pubchem', pubchemCid: r.cid });
    if (r && r.status === 'notfound') return null;                  // not a real compound
    return Object.assign(c, { verified: 'unchecked' });              // network problem: try again later
  }));

  h.compounds = checked.filter(Boolean);
  if (JSON.stringify(h.compounds) !== before) result.changed = true;
  result.unchecked = h.compounds.filter(c => c.verified === 'unchecked').length;
  if (!h._compoundsCheckedAt) { h._compoundsCheckedAt = new Date().toISOString(); result.changed = true; }
  return result;
}

// What users get to see: compounds that have actually been confirmed.
// 'unchecked' ones stay in storage (so they can be re-checked) but are
// never displayed until confirmed.
function forDisplay(h) {
  if (!h || !Array.isArray(h.compounds)) return h;
  return Object.assign({}, h, { compounds: h.compounds.filter(c => c && c.verified !== 'unchecked') });
}

module.exports = {
  verifyCompounds,
  forDisplay,
  cleanCompoundName,
  REQUIRED_TEXT,
  REQUIRED_SECTIONS,
  REQUIRED_TEXT_SECTIONS,
  hasInteractionsField,
  findMissing,
  deriveFunctionalOverview,
  validateCompounds,
  REAL_COMPOUNDS
};
